def line(p,a):
    v=S[p][a]; sl=v["slopes_max"]; return f"| {p} | {a} | "+", ".join("" if x is None else f"{x:.2f}" for x in sl[1:])+f" | {v['floor_max']:.2e} (k={v['k_at_floor']}) | "+(f"h*=1/{2**v['crossover_vs_direct_3x']['k']}" if v['crossover_vs_direct_3x'] else "-")+" | "+(", ".join(f"1/{2**k}" for k in v['failed_k']) if v['failed_k'] else "-")+" | "+("" if not v['eta_growth'] else f"{v['eta_growth']['exponent_eta_vs_h']:.2f}")+" |"
rows=[line(p,a) for p in ("p2","p1pr","p1") for a in ("direct","gmres:1e-12","gmres:1e-9","gmres:1e-6","gmres:1e-3","forcing:1e-4","forcing:1e-6","forcing:1e-8","forcing:1e-10") if a in S[p]]
ad=[f"| {p} | {x['rtol']} | {x['err_max']:.2e} | {x['err_over_rtol']:.2f} | {x['accepted']}/{x['rejected']} | {x['linear_solve_failures']} | {x['linear_iterations']} |" for p in ("p1","p2") for x in sorted(S[p]["adaptive"],key=lambda x:-float(x["rtol"]))]
r=open("README.md").read()
import re
head=r.split("| problem | arm | slopes")[0]; tail=r.split("## Free adaptive integrator")[1]
tail_rows_end=tail.index("\n\n## Problems")
tail_new=tail[:tail.index("|---|---|---|---|---|---|---|\n")+len("|---|---|---|---|---|---|---|\n")]+"\n".join(ad)+tail[tail_rows_end:]
mid="| problem | arm | slopes k=4..10 | floor (k, failed rows excluded) | h* | failed at h | eta exponent |\n|---|---|---|---|---|---|---|\n"+"\n".join(rows)+"\n\nFull per-row table (errors, endpoint slopes, rejections, rhs/jvp/linear_iterations, eta/tau): `table.md`; machine-readable: `analysis.json`, `results.json`. Plots: `e04_p2.png`, `e04_p1pr.png`, `e04_p1.png`, `e04_p1ns.png` (red stars = free adaptive integrator at rtol 1e-4..1e-10).\n\n## Free adaptive integrator"
open("README.md","w").write(head+mid+tail_new); print("finalized")
